function parseDuration(text) {
  if (typeof text !== 'string') throw new RangeError('expected a string');
  const match = /^\s*(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?\s*$/.exec(text);
  if (!match || match.slice(1).every((part) => part === undefined)) {
    throw new RangeError(`invalid duration: ${JSON.stringify(text)}`);
  }
  const [hours, minutes, seconds] = match.slice(1).map((part) => (part === undefined ? 0 : Number(part)));
  return hours * 3600 + minutes * 60 + seconds;
}

module.exports = { parseDuration };

