from decimal import ROUND_HALF_UP, Decimal

from pricing import CENT, apply_discount, to_decimal


class Cart:
    def __init__(self):
        self.items = []

    def add(self, name, price, quantity=1):
        if quantity < 0:
            raise ValueError("quantity must not be negative")
        self.items.append((name, to_decimal(price), quantity))

    def subtotal(self):
        total = sum((price * quantity for _, price, quantity in self.items), Decimal(0))
        return total.quantize(CENT, rounding=ROUND_HALF_UP)

    def total(self, discount_percent=0):
        return apply_discount(self.subtotal(), discount_percent)

