import time
from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, ttl, clock=time.monotonic):
        if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity <= 0:
            raise ValueError("capacity must be a positive integer")
        if isinstance(ttl, bool) or not isinstance(ttl, (int, float)) or ttl <= 0:
            raise ValueError("ttl must be a positive number")
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self._entries = OrderedDict()

    def _alive(self, stored_at, now):
        return now - stored_at < self.ttl

    def get(self, key, default=None):
        now = self.clock()
        entry = self._entries.get(key)
        if entry is None:
            return default
        if not self._alive(entry[1], now):
            del self._entries[key]
            return default
        self._entries.move_to_end(key)
        return entry[0]

    def set(self, key, value):
        now = self.clock()
        self._entries[key] = (value, now)
        self._entries.move_to_end(key)
        if len(self._entries) > self.capacity:
            for stale in [k for k, (_, at) in self._entries.items() if not self._alive(at, now)]:
                del self._entries[stale]
            while len(self._entries) > self.capacity:
                self._entries.popitem(last=False)

    def delete(self, key):
        now = self.clock()
        entry = self._entries.pop(key, None)
        return entry is not None and self._alive(entry[1], now)

    def __len__(self):
        return len(self.keys())

    def keys(self):
        now = self.clock()
        return [k for k, (_, at) in self._entries.items() if self._alive(at, now)]

    def __contains__(self, key):
        entry = self._entries.get(key)
        return entry is not None and self._alive(entry[1], self.clock())

