from decimal import Decimal, InvalidOperation


def parse_amount(text):
    """'1,234.50' -> Decimal('1234.50'); '(12.50)' -> Decimal('-12.50')."""
    text = text.strip()
    negative = text.startswith("(") and text.endswith(")")
    if negative:
        text = text[1:-1].strip()
    try:
        value = Decimal(text.replace(",", ""))
    except InvalidOperation:
        raise ValueError(f"bad amount: {text!r}") from None
    return -value if negative else value


def load(lines):
    """Parse 'date;account;amount' lines. Blank lines and # comments are skipped;
    account names are case-insensitive and reported in lower case."""
    entries = []
    for number, line in enumerate(lines, start=1):
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        parts = line.split(";")
        if len(parts) != 3:
            raise ValueError(f"line {number}: expected date;account;amount")
        date, account, amount = (part.strip() for part in parts)
        try:
            value = parse_amount(amount)
        except ValueError as error:
            raise ValueError(f"line {number}: {error}") from None
        entries.append((date, account.lower(), value))
    return entries


def balances(entries, start=None, end=None):
    """Sum amounts per account for entries dated from start to end, both inclusive."""
    totals = {}
    for date, account, amount in entries:
        if start is not None and date < start:
            continue
        if end is not None and date > end:
            continue
        totals[account] = totals.get(account, Decimal(0)) + amount
    return totals

