const NUMBER = /^(0|[1-9]\d*)$/;
const WILDCARD = new Set(['*', 'x', 'X']);

function parseVersion(text) {
  const parts = String(text).split('.');
  if (parts.length !== 3 || !parts.every((part) => NUMBER.test(part))) {
    throw new TypeError(`invalid version: ${text}`);
  }
  return parts.map(Number);
}

function compare(a, b) {
  for (let i = 0; i < 3; i++) if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1;
  return 0;
}

// The numbers of a partial version up to its first wildcard, or null.
function parsePartial(text) {
  if (WILDCARD.has(text)) return [];
  const parts = text.split('.');
  if (parts.length > 3) return null;
  const numbers = [];
  for (let i = 0; i < parts.length; i++) {
    if (WILDCARD.has(parts[i])) {
      return parts.slice(i).every((part) => WILDCARD.has(part)) ? numbers : null;
    }
    if (!NUMBER.test(parts[i])) return null;
    numbers.push(Number(parts[i]));
  }
  return numbers;
}

function bounds(numbers) {
  const lower = [...numbers, 0, 0].slice(0, 3);
  const upper = numbers.length === 1 ? [numbers[0] + 1, 0, 0] : [numbers[0], numbers[1] + 1, 0];
  return [['>=', lower], ['<', upper]];
}

function term(text) {
  const operator = /^(>=|<=|>|<|=)(.*)$/.exec(text);
  if (operator) return [[operator[1], parseVersion(operator[2])]];
  if (text.startsWith('^')) {
    const v = parseVersion(text.slice(1));
    const upper = v[0] > 0 ? [v[0] + 1, 0, 0] : v[1] > 0 ? [0, v[1] + 1, 0] : [0, 0, v[2] + 1];
    return [['>=', v], ['<', upper]];
  }
  if (text.startsWith('~')) {
    const numbers = parsePartial(text.slice(1));
    if (!numbers || numbers.length === 0) throw new TypeError(`invalid term: ${text}`);
    return numbers.length === 3 ? [['>=', numbers], ['<', [numbers[0], numbers[1] + 1, 0]]] : bounds(numbers);
  }
  const numbers = parsePartial(text);
  if (!numbers) throw new TypeError(`invalid term: ${text}`);
  if (numbers.length === 0) return [];
  return numbers.length === 3 ? [['=', numbers]] : bounds(numbers);
}

function comparatorSet(text) {
  const tokens = text.trim().split(/\s+/).filter(Boolean);
  if (tokens.length === 0) throw new TypeError('empty comparator set');
  if (tokens.length === 3 && tokens[1] === '-') {
    return [['>=', parseVersion(tokens[0])], ['<=', parseVersion(tokens[2])]];
  }
  if (tokens.includes('-')) throw new TypeError(`invalid range: ${text}`);
  return tokens.flatMap(term);
}

function holds(version, [operator, bound]) {
  const order = compare(version, bound);
  return { '=': order === 0, '>': order > 0, '>=': order >= 0, '<': order < 0, '<=': order <= 0 }[operator];
}

function satisfies(version, range) {
  const v = parseVersion(version);
  if (typeof range !== 'string') throw new TypeError('range must be a string');
  const sets = range.split('||').map(comparatorSet);
  return sets.some((set) => set.every((comparator) => holds(v, comparator)));
}

module.exports = { satisfies };

