import math


class Circle:
    def __init__(self, radius):
        if radius <= 0:
            raise ValueError("radius must be positive")
        self.radius = radius

    def area(self):
        return math.pi * self.radius ** 2

    def perimeter(self):
        return 2 * math.pi * self.radius


class Rectangle:
    def __init__(self, width, height):
        if width <= 0 or height <= 0:
            raise ValueError("sides must be positive")
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

    def perimeter(self):
        return 2 * (self.width + self.height)


def describe(shape):
    if isinstance(shape, Circle):
        return "circle r=%s area=%.2f perimeter=%.2f" % (shape.radius, shape.area(), shape.perimeter())
    if isinstance(shape, Rectangle):
        return "rectangle %sx%s area=%.2f perimeter=%.2f" % (
            shape.width, shape.height, shape.area(), shape.perimeter())
    raise TypeError("unknown shape")


def total_area(shapes):
    total = 0
    for shape in shapes:
        total += shape.area()
    return total

