from abc import ABC, abstractmethod


class Shape(ABC):
    @abstractmethod
    def area(self):
        """The area of the shape."""

    @abstractmethod
    def perimeter(self):
        """The length of its outline."""

    @abstractmethod
    def label(self):
        """What the shape is and how big, as describe() prints it."""

    def describe(self):
        return "%s area=%.2f perimeter=%.2f" % (self.label(), self.area(), self.perimeter())

